### P1923
```C++
#include<cstdio>
#include<algorithm>
#define MAXN 5000010
using namespace std;

int a[MAXN];
int n,k;

int f(int a[],int low,int high){
    if (low==high){
        return low;
    }

    int mid=low+(high-low)/2;

    if (a[low]>a[mid]) swap(a[low],a[mid]);
    if (a[low]>a[high]) swap(a[low],a[high]);
    if (a[mid]>a[high]) swap(a[mid],a[high]);

    int pivot=a[mid];
    swap(a[mid],a[high]);

    int i=low-1;

    for (int j=low;j<high;j++){
        if (a[j]<=pivot){
            i++;
            swap(a[i],a[j]);
        }
    }

    swap(a[i+1],a[high]);
    return i+1;
}

int g(int a[],int low,int high){   
    int pi=f(a,low,high);

    if (pi<k) return g(a,pi+1,high);
    else if (pi>k) return g(a,low,pi-1);
    else return a[pi];
}

int main(){

    scanf("%d %d", &n, &k);
    for (int i=0;i<n;i++){
        scanf("%d", &a[i]);
    }
    printf("%d\n", g(a,0,n-1));
    return 0;
}
```
<p style="color:red;font-size:20px">快速排序</p>
改进之前的快速排序写法，将while循环优化成for循环，并将pivot位置放到high而非high-1
大量数据的输入停止使用cin/cout，而是scanf/printf


