### P1093
```C++
#include<cstdio>
#include<iostream>
#include<algorithm>
#define MAXN 310
using namespace std;

struct Student{
    int id;
    int chinese;
    int math;
    int english;
    int total;
};

struct Student stu[MAXN];
int n;

bool compare(struct Student& a,struct Student& b){
    if (a.total!=b.total) return a.total>b.total;
    else {
        if (a.chinese!=b.chinese) return a.chinese>b.chinese;
        else {
            return a.id<b.id;
        }
    }
}

int main(){
    cin>>n;
    for (int i=0;i<n;i++){
        cin>>stu[i].chinese>>stu[i].math>>stu[i].english;
        stu[i].id=i+1;
        stu[i].total=stu[i].chinese+stu[i].math+stu[i].english;
    }
    sort(stu,stu+n,compare);
    for (int i=0;i<5;i++){
        cout<<stu[i].id<<' '<<stu[i].total<<'\n';
    }
    cout<<endl;
    return 0;
}
```
就是用来熟悉sort（）函数，sort（ptr1,ptr2，compare），ture时ptr1在ptr2前面

### P1781
```C++
#include<cstdio>
#include<iostream>
#include<cstring>
#include<algorithm>
#define MAXN 30
using namespace std;

struct BigInt{
    int digit[110];
    int len=0;
    int id;

    BigInt(){

    }

    BigInt(string s,int index){
        memset(digit,0,sizeof(digit));
        int l=s.length();
        do {
            digit[len]=s[l-len-1];
            len++;
        }while (len<l);
        id=index;
    }

    bool compareTo(BigInt b){
        if (len==b.len){
            for (int i=len-1;i>=0;i--){
                if (digit[i]>b.digit[i]) return true;
                else if (digit[i]<b.digit[i]) return false;
            }
        }
        else {
            return len>b.len;
        }
    }

    string toString(){
        string s="";
        for (int i=len-1;i>=0;i--){
            s+=(char) digit[i];
        }
        return s;
    }
};

struct BigInt votes[MAXN];
int n;

bool cmp(BigInt a,BigInt b){
    return a.compareTo(b);
}

int main(){
    scanf("%d",&n);
    getchar();
    for (int i=0;i<n;i++){
        string s;
        cin>>s;
        votes[i]=BigInt(s,i+1);
    }
    sort(votes,votes+n,cmp);
    cout<<votes[0].id<<'\n'<<votes[0].toString()<<endl;
    return 0;
}
```
实现BigInt中的比大小
> 字符串可以直接比大小（字典序） <br/>
> 可以记录最大字符串和对应id，然后一直维护，避免了结构体和sort


