### p1116
```C++
#include<iostream>
#include<cstdio>
#define MAXN 10010
using namespace std;

int m[MAXN];
int n;

int f(int m[],int left,int mid,int right){
    int res=0;
    int len1=mid-left+1;
    int len2=right-mid;

    int a[len1],b[len2];
    for (int i=0;i<len1;i++) a[i]=m[left+i];
    for (int j=0;j<len2;j++) b[j]=m[mid+1+j];

    int i=0,j=0,k=left;
    while (i<len1 && j<len2){
        if (a[i]<=b[j]){
            m[k++]=a[i++];
        }
        else {
            m[k++]=b[j++];
            res+=len1-i;
        }
    }
    while (i<len1){
        // res+=len2;
        m[k++]=a[i++];
    }
    while (j<len2){
        m[k++]=b[j++];
    }
    return res;
}

int g(int m[],int left,int right){
    int ans=0;
    int mid=left+(right-left)/2;

    if (left<right){
        ans+=g(m,left,mid);
        ans+=g(m,mid+1,right);
        ans+=f(m,left,mid,right);
    }
    return ans;
}

int main(){
    cin>>n;
    for (int i=0;i<n;i++){
        cin>>m[i];
    }
    cout<<g(m,0,n-1)<<endl;
    return 0;
}
```
<p style="color:red;font-size:20px">归并排序</p>

**定理**:给定一个包含 N 个互不相同元素的数列 A，将其通过一系列相邻元素交换操作，最终排列成单调序列（例如升序或降序）所需的最少交换次数，恰好等于该数列中初始状态下的逆序对（Inversion Pair）的总数。同时，也必然存在一种通过相邻交换达到此最少次数的排序方式,即**冒泡排序**。


