### 1104
```C++
#include<algorithm>
#include<iostream>
#include<string>
#define MAXN 110
using namespace std;

struct oier{
    int id;
    string s;
    int y;
    int m;
    int d;
};

bool cmp(struct oier a,struct oier b){
    if (a.y==b.y){
        if (a.m==b.m){
            if (a.d==b.d){
                return a.id>b.id;
            }
            else {
                return a.d<b.d;
            }
        }
        else {
            return a.m<b.m;
        }
    }
    else {
        return a.y<b.y;
    }
}

struct oier oiers[MAXN];
int n;

int main(){
    cin>>n;
    for (int i=0;i<n;i++){
        oiers[i].id=i;
        cin>>oiers[i].s>>oiers[i].y>>oiers[i].m>>oiers[i].d;
    }
    sort(oiers,oiers+n,cmp);
    for (int i=0;i<n;i++){
        cout<<oiers[i].s<<'\n';
    }
    cout<<endl;
    return 0;
}
```
常规sort函数的应用


